@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/banner.css (Figma Banner 7275:15120). Tones set ONLY --_nz-* privates; public
   --nz-banner-* hooks are read once, at the property, and never assigned here. Figma: 16 / 24
   padding, 20 between parts, radius/xl, the text in a column (Heading/H4 over Body/M), the action and
   the dismiss after it, everything centred on the row. Below about 36rem of room the action wraps
   under the text. */
@layer nz.components {
  .nz-banner {
    /* defaults = Figma Promo (tone "brand", D-bq) */
    --_nz-banner-bg: var(--nz-bg-brand-subtle);
    --_nz-banner-icon-fg: var(--nz-icon-brand);

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-banner-gap, var(--nz-space-5));
    padding-block: var(--nz-banner-padding-block, var(--nz-space-4));
    padding-inline: var(--nz-banner-padding-inline, var(--nz-space-6));
    border-radius: var(--nz-banner-radius, var(--nz-radius-xl));
    background: var(--nz-banner-bg, var(--_nz-banner-bg));
    color: var(--nz-text-primary);
  }

  .nz-banner[data-tone='warning'] {
    --_nz-banner-bg: var(--nz-bg-warning-subtle);
    --_nz-banner-icon-fg: var(--nz-icon-warning);
  }

  .nz-banner-icon {
    display: inline-flex;
    flex: none;
    color: var(--nz-banner-icon-fg, var(--_nz-banner-icon-fg));
    font-size: var(--nz-size-icon-lg);

    & > svg {
      inline-size: 1em;
      block-size: 1em;
    }
  }

  /* Figma's 72 px render */
  .nz-banner-media {
    display: inline-flex;
    flex: none;
    inline-size: 4.5rem;
    block-size: 4.5rem;
    overflow: hidden;

    & > :is(img, svg, picture, video) {
      inline-size: 100%;
      block-size: 100%;
      object-fit: contain;
    }
  }

  .nz-banner-content {
    display: flex;
    flex: 1 1 16rem;
    flex-direction: column;
    gap: var(--nz-space-0-5);
    min-inline-size: 0;
  }

  .nz-banner-title {
    font: var(--nz-banner-title-font, var(--nz-font-heading-h4));
    letter-spacing: var(--nz-tracking-heading-h4);
  }

  .nz-banner-description {
    color: var(--nz-text-secondary);
    font: var(--nz-banner-description-font, var(--nz-font-body-m));
    letter-spacing: var(--nz-tracking-body-m);
  }

  .nz-banner-action {
    display: flex;
    flex: none;
    flex-wrap: wrap;
    gap: var(--nz-space-2);
  }

  /* The default BannerDismiss is a tertiary md IconButton (icon-button.css draws it), last on the
     row; it keeps to the row's end when the action wraps. */
  .nz-banner-dismiss {
    flex: none;
    margin-inline-start: auto;
  }

  .nz-banner > .nz-icon-button.nz-banner-dismiss {
    --_nz-icon-button-fg: var(--nz-banner-dismiss-fg, var(--nz-icon-secondary));
  }

  /* backgrounds are replaced: an outline keeps the banner's edge without changing its size */
  @media (forced-colors: active) {
    .nz-banner {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
  }
}
